import type { ExerciseQuestion } from "../types";

export const ARTICLE_QUESTIONS: ExerciseQuestion[] = [
  { id: "a001", question: "She is ___ honest person.", options: ["a", "an", "the", "-"], correctIndex: 1, explanation: "Mạo từ 'a' hay 'an' được chọn theo âm thanh của từ đứng ngay sau, không phải theo chữ cái đầu tiên. 'Honest' có chữ 'h' câm nên âm đầu thực chất là nguyên âm /ɒ/, vì vậy phải dùng 'an'. Nhiều người thấy chữ 'h' liền chọn 'a', nhưng đây chính là trường hợp ngoại lệ cần nhớ, giống như 'hour' hay 'honor'." },
  { id: "a002", question: "He ate ___ apple for breakfast.", options: ["a", "an", "the", "-"], correctIndex: 1, explanation: "Trước danh từ số ít bắt đầu bằng âm nguyên âm, ta dùng 'an' thay vì 'a'. 'Apple' phát âm là /æpl/, mở đầu bằng nguyên âm nên chọn 'an' là đúng. Đừng nhầm với 'the', vì đây là lần đầu nhắc đến quả táo này nên chưa thể coi là vật đã biết." },
  { id: "a003", question: "___ university is ___ place of higher learning.", options: ["A/a", "An/an", "A/the", "The/a"], correctIndex: 0, explanation: "Mạo từ phụ thuộc vào âm thanh chứ không phải mặt chữ: dù 'university' viết bằng nguyên âm 'u', nó được phát âm là /juː-/ với âm bán nguyên âm /j/ giống phụ âm, nên phải dùng 'a'. Tương tự, 'place' bắt đầu bằng phụ âm /p/ nên cũng đi với 'a'. Rất nhiều học viên bị đánh lừa chọn 'an' chỉ vì nhìn thấy chữ 'u' đứng đầu, nhưng quy tắc luôn dựa vào âm thanh thực tế khi đọc." },
  { id: "a004", question: "I need ___ hour to finish this report.", options: ["a", "an", "the", "-"], correctIndex: 1, explanation: "'Hour' có chữ 'h' câm nên khi đọc, âm đầu tiên nghe được là nguyên âm /aʊ/, do đó phải dùng 'an' chứ không phải 'a'. Đây là quy tắc mạo từ dựa trên âm thanh, không dựa trên chữ viết. Hãy nhớ nhóm từ h câm này (hour, honest, honor) để tránh chọn nhầm 'a'." },
  { id: "a005", question: "She drives ___ European car.", options: ["a", "an", "the", "-"], correctIndex: 0, explanation: "Dù 'European' bắt đầu bằng nguyên âm 'E' trên mặt chữ, âm đọc thực tế lại là /j/ (giống 'y'), một âm mang tính chất phụ âm, nên mạo từ đúng là 'a'. Đây là lỗi phổ biến vì học viên thường chỉ nhìn chữ cái đầu tiên mà quên kiểm tra cách phát âm. Nếu chọn 'an' ở đây là sai, vì âm /j/ không phải là âm nguyên âm." },
  { id: "a006", question: "He is ___ engineer working at a tech company.", options: ["a", "an", "the", "-"], correctIndex: 1, explanation: "'Engineer' mở đầu bằng âm nguyên âm /ɛ/, nên theo quy tắc mạo từ, ta phải dùng 'an'. Câu này khá đơn giản vì cả chữ viết lẫn cách đọc đều là nguyên âm, không có ngoại lệ như 'hour' hay 'university'. Chọn 'a' ở đây sẽ sai vì tai người nghe sẽ thấy hai âm nguyên âm bị dính vào nhau, nghe không tự nhiên." },
  { id: "a007", question: "___ useful tool can save a lot of time.", options: ["A", "An", "The", "-"], correctIndex: 0, explanation: "Chữ 'useful' tuy bắt đầu bằng nguyên âm 'u' nhưng lại được phát âm là /juːsfl/, tức là âm /j/ giống phụ âm, nên phải chọn 'A' chứ không phải 'An'. Quy tắc cốt lõi vẫn là dựa vào âm thanh khi nói ra, không phải chữ cái viết trên giấy. Nhóm từ bắt đầu bằng u nhưng đọc là /j/ như 'useful', 'university', 'uniform' đều đi với 'a'." },
  { id: "a008", question: "She bought ___ one-bedroom apartment downtown.", options: ["a", "an", "the", "-"], correctIndex: 0, explanation: "'One' được phát âm là /wʌn/, bắt đầu bằng âm bán nguyên âm /w/ mang tính phụ âm, nên phải dùng 'a' thay vì 'an'. Đây là một ví dụ khác cho thấy chữ viết có thể đánh lừa nếu không để ý cách đọc thật sự. Nếu chọn 'an' vì thấy từ bắt đầu có vẻ là nguyên âm sẽ bị sai hoàn toàn." },
  { id: "a009", question: "She plays ___ piano beautifully.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Khi nói về việc chơi một loại nhạc cụ như kỹ năng, tiếng Anh dùng 'the' đứng trước tên nhạc cụ, ví dụ 'play the piano', 'play the guitar'. Ở đây câu đang nói về khả năng chơi đàn piano của cô ấy nên 'the' là lựa chọn chuẩn. Không dùng 'a' vì đây không phải chỉ một cây đàn piano cụ thể mà là nói đến bộ môn/nhạc cụ nói chung theo cách quy ước này." },
  { id: "a010", question: "___ Amazon is the longest river in South America.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Tên các con sông luôn đi kèm mạo từ 'the', ví dụ 'the Amazon', 'the Nile', 'the Mekong', vì đó là quy tắc cố định cho các đặc điểm địa lý loại này. Ở câu này, 'the Amazon' chỉ dòng sông cụ thể và nổi tiếng nên bắt buộc phải có 'the'. Nhiều người quên mất và bỏ mạo từ (chọn '-'), nhưng tên sông là một trong những ngoại lệ luôn cần 'the'." },
  { id: "a011", question: "Can you pass me ___ salt, please?", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "'The' được dùng khi cả người nói và người nghe đều hiểu rõ đang nói đến vật cụ thể nào, ở đây là lọ muối trên bàn ăn. Vì hai người đang ngồi cùng bàn, 'the salt' là vật xác định trong ngữ cảnh đó chứ không phải muối nói chung. Nếu dùng 'a salt' sẽ sai vì muối là danh từ không đếm được và câu này không nói đến 'một loại muối' bất kỳ." },
  { id: "a012", question: "___ Sun rises in the east.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Các vật thể duy nhất trên thế giới hoặc vũ trụ như mặt trời, mặt trăng, trái đất luôn đi với 'the' vì chỉ có một mà thôi: the Sun, the Moon, the Earth. Câu này nói về việc mặt trời mọc ở đằng đông, một sự thật hiển nhiên và duy nhất nên chọn 'the'. Sẽ không hợp lý nếu dùng 'a Sun' vì điều đó ngụ ý có nhiều mặt trời khác nhau." },
  { id: "a013", question: "___ rich are getting richer.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Cấu trúc 'the + tính từ' được dùng để chỉ một nhóm người mang đặc điểm đó, 'the rich' nghĩa là 'những người giàu' nói chung. Câu này đang nói về xu hướng của cả nhóm người giàu trong xã hội nên cần 'the' đứng trước tính từ. Không thể dùng 'a rich' vì tính từ không thể đứng một mình sau mạo từ 'a' để chỉ một nhóm người như vậy." },
  { id: "a014", question: "She lives in ___ south of France.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Các vùng miền địa lý trong một quốc gia như miền nam, miền bắc thường đi kèm 'the': 'the south of France', 'the north of England'. Ở đây câu nói đến một khu vực cụ thể của nước Pháp nên 'the' là đáp án đúng. Bỏ mạo từ (chọn '-') sẽ sai vì đây không phải tên riêng độc lập mà là cách diễn đạt vùng miền luôn cần 'the'." },
  { id: "a015", question: "I read ___ interesting book last week. ___ book was about history.", options: ["a/The", "the/A", "an/The", "the/An"], correctIndex: 2, explanation: "Quy tắc quan trọng: lần đầu nhắc đến một vật chưa xác định thì dùng 'a/an', nhưng khi nhắc lại lần hai, vật đó đã trở nên xác định nên phải chuyển sang 'the'. 'Interesting' bắt đầu bằng nguyên âm nên là 'an', còn ở câu sau, 'the book' chỉ đúng cuốn sách vừa nhắc. Nếu vẫn dùng 'a' ở câu hai sẽ sai logic, vì lúc này người nghe đã biết cuốn sách nào đang được nói tới." },
  { id: "a016", question: "She is studying ___ medicine at university.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên các môn học hoặc ngành học khi nói chung (medicine, history, physics...) không cần mạo từ, đây gọi là zero article. Câu này nói về việc theo học ngành y nói chung tại trường đại học nên không thêm 'a/an/the'. Nếu thêm 'the' vào sẽ ngụ ý một môn y học cụ thể nào đó đã được nhắc trước, điều này không đúng với ngữ cảnh câu." },
  { id: "a017", question: "___ Mount Everest is the world's highest peak.", options: ["A", "An", "The", "-"], correctIndex: 3, explanation: "Tên riêng của một ngọn núi đơn lẻ không đi với mạo từ nào cả: Mount Everest, Mount Fuji. Vì đây là tên riêng xác định sẵn, câu này dùng zero article là chính xác. Nhưng cần phân biệt với dãy núi gồm nhiều đỉnh, ví dụ 'the Alps', 'the Himalayas', nơi bắt buộc phải có 'the'." },
  { id: "a018", question: "He goes to ___ church every Sunday.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Khi nhắc đến các địa điểm quen thuộc theo đúng chức năng vốn có của nó (đi lễ, đi học, đi khám bệnh), tiếng Anh bỏ mạo từ: go to church, go to school, go to hospital. Câu này nói về việc đi nhà thờ để hành lễ mỗi Chủ nhật nên dùng zero article. Nếu thêm 'the' vào, câu sẽ mang nghĩa khác: đến tòa nhà nhà thờ đó vì một lý do khác, chẳng hạn để sửa chữa hay tham quan." },
  { id: "a019", question: "I had ___ breakfast before leaving.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên các bữa ăn (breakfast, lunch, dinner) khi nói chung, không có tính từ mô tả, thường không cần mạo từ. Câu này chỉ đơn giản nói về việc ăn sáng trước khi ra ngoài nên chọn zero article là hợp lý. Chỉ khi có tính từ đứng trước bữa ăn, như 'a big breakfast', ta mới cần thêm mạo từ 'a'." },
  { id: "a020", question: "She traveled to London by ___ train.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Sau giới từ 'by' khi nói về phương tiện di chuyển, ta không dùng mạo từ: by car, by bus, by train, by plane. Câu này miêu tả cách cô ấy đi đến London nên đúng ngữ pháp là 'by train' không có 'the' hay 'a'. Nếu thêm 'the' vào ('by the train') câu sẽ mang nghĩa khác hẳn, ám chỉ một chuyến tàu cụ thể chứ không phải phương thức di chuyển nói chung." },
  { id: "a021", question: "I was born ___ July 15, 1995.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Giới từ 'on' luôn đi với ngày tháng cụ thể như ngày trong tuần hay ngày dương lịch: on July 15, on Monday. Câu này nêu một ngày sinh cụ thể nên 'on' là lựa chọn chuẩn. Đừng nhầm với 'in', vốn dùng cho những mốc thời gian rộng hơn như tháng hay năm." },
  { id: "a022", question: "The meeting starts ___ 3 PM.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Giờ giấc cụ thể trong ngày luôn đi với giới từ 'at': at 3 PM, at noon, at midnight. Câu này nói về thời điểm chính xác cuộc họp bắt đầu nên 'at' là đáp án đúng. 'In' sẽ sai ở đây vì 'in' chỉ dùng cho khoảng thời gian dài hơn như buổi sáng, tháng hay năm, không dùng cho một mốc giờ cụ thể." },
  { id: "a023", question: "She was born ___ 1998.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Giới từ 'in' được dùng với các mốc thời gian dài như năm, tháng, mùa hoặc thế kỷ: in 1998, in July, in summer. Câu này nói về năm sinh nên chọn 'in' là chính xác. 'At' sẽ không phù hợp vì giới từ này chỉ dùng cho các thời điểm rất ngắn và cụ thể như giờ giấc." },
  { id: "a024", question: "I'll see you ___ the morning.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Các buổi trong ngày (sáng, chiều, tối) luôn đi với 'in': in the morning, in the afternoon, in the evening. Câu này hẹn gặp vào buổi sáng nên 'in' là lựa chọn đúng. Ngoại lệ duy nhất là buổi đêm dùng 'at night', còn lại đều dùng 'in' chứ không phải 'on' hay 'at'." },
  { id: "a025", question: "The store is open ___ weekends.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Các ngày cụ thể trong tuần và những dịp lặp lại theo ngày như cuối tuần luôn dùng 'on': on Mondays, on weekends. Câu này nói cửa hàng mở cửa vào các ngày cuối tuần nên 'on' là đúng. 'In' sẽ sai vì giới từ đó chỉ phù hợp với khoảng thời gian lớn hơn như tháng hay mùa." },
  { id: "a026", question: "She always feels tired ___ the end of the day.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Đây là cụm cố định 'at the end of' mang nghĩa 'vào lúc cuối của', luôn đi với 'at' bất kể ngữ cảnh. Câu này nói cô ấy mệt vào cuối ngày nên phải dùng 'at the end of the day'. Học thuộc cụm này như một khối cố định sẽ tránh nhầm lẫn với 'in' hay 'on', vốn không đi với cấu trúc này." },
  { id: "a027", question: "He arrived ___ midnight.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Các thời điểm đặc biệt trong ngày như nửa đêm, giữa trưa, lúc bình minh luôn dùng 'at': at midnight, at noon, at dawn. Câu này nói anh ấy đến vào lúc nửa đêm nên 'at' là lựa chọn chính xác. 'In' hay 'on' không dùng được ở đây vì đây là một thời điểm rất cụ thể, không phải khoảng hay ngày." },
  { id: "a028", question: "She left ___ the morning of June 3rd.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Khi nói về buổi sáng/chiều/tối của một ngày cụ thể có kèm ngày tháng, giới từ chuyển từ 'in' sang 'on': on the morning of June 3rd. Câu này nêu rõ ngày 3 tháng 6 nên phải dùng 'on' thay vì 'in the morning' thông thường. Đây là điểm dễ nhầm vì học viên hay áp dụng máy móc quy tắc 'in the morning' mà quên rằng khi có ngày cụ thể đi kèm, giới từ sẽ đổi thành 'on'." },
  { id: "a029", question: "Please submit your application ___ Friday.", options: ["until", "by", "on", "in"], correctIndex: 1, explanation: "Giới từ 'by' mang nghĩa 'không muộn hơn', dùng để chỉ hạn chót (deadline). Câu này yêu cầu nộp đơn trước hoặc đúng thứ Sáu nên 'by' là lựa chọn phù hợp. 'Until' dễ bị nhầm nhưng 'until' diễn tả một hành động kéo dài liên tục đến một mốc, không phù hợp với ý nghĩa 'hạn chót' của câu." },
  { id: "a030", question: "She waited ___ the bus for 30 minutes.", options: ["to", "for", "at", "by"], correctIndex: 1, explanation: "Cụm động từ cố định 'wait for something/someone' nghĩa là chờ đợi ai/cái gì, luôn cần giới từ 'for' theo sau. Câu này nói về việc chờ xe buýt nên phải dùng 'wait for the bus'. Đừng nhầm với 'wait to' hay 'wait at', vì 'wait for' mới đúng khi đối tượng chờ đợi là một danh từ." },
  { id: "a031", question: "The keys are ___ the table.", options: ["in", "on", "at", "under"], correctIndex: 1, explanation: "Giới từ 'on' diễn tả vị trí trên một bề mặt phẳng nằm ngang: on the table, on the floor. Câu này nói chìa khóa nằm trên mặt bàn nên 'on' là chính xác. 'In' sẽ sai vì 'in' chỉ dùng khi vật nằm bên trong một không gian kín, không phải trên bề mặt." },
  { id: "a032", question: "She lives ___ the third floor.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Khi nói về số tầng của một tòa nhà, tiếng Anh luôn dùng giới từ 'on': on the third floor, on the ground floor. Câu này nói cô ấy sống ở tầng ba nên 'on' là đáp án đúng. 'At' hay 'in' đều không phù hợp với cách diễn đạt số tầng này." },
  { id: "a033", question: "The cat is hiding ___ the sofa.", options: ["on", "in", "under", "above"], correctIndex: 2, explanation: "'Under' diễn tả vị trí ở ngay bên dưới một vật, thường có sự che khuất hoặc gần sát bề mặt phía dưới. Câu này nói con mèo trốn dưới gầm ghế sofa nên 'under' là lựa chọn hợp lý nhất. 'On' sẽ sai hoàn toàn về nghĩa vì đó là vị trí phía trên bề mặt, ngược lại với 'under'." },
  { id: "a034", question: "The bank is ___ the post office and the pharmacy.", options: ["among", "between", "beside", "within"], correctIndex: 1, explanation: "'Between' dùng khi nói đến vị trí ở giữa hai vật hoặc hai người được nêu rõ, còn 'among' dùng cho ba đối tượng trở lên. Câu này liệt kê đúng hai địa điểm (bưu điện và hiệu thuốc) nên phải chọn 'between'. Nếu có từ 'among' xuất hiện ở đây sẽ sai vì không đủ số lượng đối tượng cần cho từ này." },
  { id: "a035", question: "The picture is hanging ___ the wall.", options: ["on", "in", "at", "by"], correctIndex: 0, explanation: "Giới từ 'on' cũng dùng cho các bề mặt thẳng đứng như tường, bảng: on the wall, on the board. Câu này nói bức tranh được treo trên tường nên 'on' là đáp án chuẩn. 'In' không phù hợp vì bức tranh không nằm bên trong bức tường mà chỉ tiếp xúc với bề mặt của nó." },
  { id: "a036", question: "She is waiting ___ the bus stop.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Khi coi một địa điểm như một điểm dừng cụ thể chứ không phải không gian rộng, tiếng Anh dùng 'at': at the bus stop, at the station. Câu này nói cô ấy đang đợi ở trạm xe buýt nên 'at' là lựa chọn đúng. 'In' sẽ sai vì trạm xe buýt được xem là một điểm mốc, không phải một không gian có thể 'ở bên trong'." },
  { id: "a037", question: "I live ___ Oxford Street.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Tên đường phố cụ thể thường đi với giới từ 'on': on Oxford Street, on Main Avenue. Câu này nói về nơi ở trên một con phố cụ thể nên 'on' là đáp án phù hợp. 'In' hay 'at' ít khi dùng với cấu trúc 'sống trên đường nào đó' theo cách diễn đạt tự nhiên này." },
  { id: "a038", question: "She is looking forward ___ seeing you again.", options: ["to", "for", "at", "about"], correctIndex: 0, explanation: "Cụm động từ cố định 'look forward to + V-ing/danh từ' nghĩa là mong chờ điều gì, và 'to' ở đây là giới từ chứ không phải dấu hiệu của động từ nguyên thể. Câu này nói mong được gặp lại nên đúng cấu trúc là 'look forward to seeing you'. Đây là lỗi rất phổ biến vì học viên hay nhầm 'to' này với 'to' trước động từ nguyên mẫu." },
  { id: "a039", question: "He is good ___ mathematics.", options: ["at", "in", "for", "with"], correctIndex: 0, explanation: "Cụm tính từ cố định 'good at something' nghĩa là giỏi về lĩnh vực nào đó, luôn cần giới từ 'at'. Câu này khen anh ấy giỏi toán nên phải dùng 'good at mathematics'. 'In' là lựa chọn sai phổ biến vì học viên nhầm sang cấu trúc khác như 'interested in'." },
  { id: "a040", question: "I agree ___ what you said.", options: ["to", "with", "about", "for"], correctIndex: 1, explanation: "Cụm cố định 'agree with someone/something' nghĩa là đồng ý với ai hoặc điều gì, dùng giới từ 'with'. Câu này nói đồng ý với điều người kia vừa nói nên chọn 'with' là đúng. 'To' dễ gây nhầm lẫn vì có cấu trúc gần giống 'agree to a plan' (đồng ý làm theo một kế hoạch), nhưng ở đây đối tượng là ý kiến của một người nên cần 'with'." },
  { id: "a041", question: "She is interested ___ learning Japanese.", options: ["at", "in", "for", "about"], correctIndex: 1, explanation: "Cụm tính từ cố định 'interested in + V-ing/danh từ' nghĩa là quan tâm/hứng thú với điều gì. Câu này nói cô ấy hứng thú học tiếng Nhật nên 'in' là giới từ chính xác. 'At' là lựa chọn hay bị nhầm nhưng không đi cùng 'interested' theo cách dùng chuẩn." },
  { id: "a042", question: "He apologized ___ being late.", options: ["for", "about", "to", "of"], correctIndex: 0, explanation: "Cụm động từ cố định 'apologize for + V-ing/danh từ' nghĩa là xin lỗi vì điều gì đã xảy ra. Câu này nói xin lỗi vì đến muộn nên 'for' là giới từ đúng. 'To' dễ gây nhầm nhưng 'to' trong cấu trúc này chỉ dùng trước người được xin lỗi (apologize to someone), không dùng trước lý do." },
  { id: "a043", question: "They are afraid ___ making mistakes.", options: ["from", "about", "of", "for"], correctIndex: 2, explanation: "Cụm tính từ cố định 'afraid of + V-ing/danh từ' nghĩa là sợ điều gì. Câu này nói sợ mắc sai lầm nên 'of' là giới từ chuẩn. 'About' là lựa chọn gây nhầm lẫn thường gặp, nhưng 'afraid' luôn đi với 'of' chứ không phải 'about'." },
  { id: "a044", question: "She is responsible ___ managing the team.", options: ["for", "of", "to", "about"], correctIndex: 0, explanation: "Cụm tính từ cố định 'responsible for + V-ing/danh từ' nghĩa là chịu trách nhiệm về việc gì. Câu này nói chịu trách nhiệm quản lý đội nhóm nên 'for' là đáp án đúng. 'Of' là lỗi phổ biến cần tránh vì 'responsible' không bao giờ đi với 'of'." },
  { id: "a045", question: "He succeeded ___ passing the exam.", options: ["in", "at", "on", "with"], correctIndex: 0, explanation: "Cụm động từ cố định 'succeed in + V-ing' nghĩa là thành công trong việc gì. Câu này nói thành công vượt qua kỳ thi nên 'in' là giới từ chuẩn xác. 'At' hay bị chọn nhầm vì gần nghĩa với 'good at', nhưng 'succeed' luôn cần 'in'." },
  { id: "a046", question: "She complained ___ the poor service.", options: ["about", "of", "at", "on"], correctIndex: 0, explanation: "Cụm động từ cố định 'complain about + danh từ' nghĩa là phàn nàn về điều gì. Câu này nói phàn nàn về dịch vụ kém nên 'about' là giới từ đúng. 'Of' dễ gây nhầm lẫn với cấu trúc khác như 'die of', nhưng 'complain' cần đi với 'about'." },
  { id: "a047", question: "He depends ___ his parents for financial support.", options: ["at", "of", "on", "for"], correctIndex: 2, explanation: "Cụm động từ cố định 'depend on + danh từ' nghĩa là phụ thuộc vào ai/điều gì. Câu này nói phụ thuộc tài chính vào bố mẹ nên 'on' là giới từ chính xác. 'On' dễ bị thay nhầm bằng 'of' hoặc 'at', nhưng chỉ 'on' mới đúng với động từ này." },
  { id: "a048", question: "She is married ___ a doctor.", options: ["with", "to", "by", "for"], correctIndex: 1, explanation: "Cụm tính từ cố định 'married to + person' nghĩa là kết hôn với ai, dùng giới từ 'to'. Câu này nói cô ấy kết hôn với một bác sĩ nên 'to' là đáp án chuẩn. 'With' là lỗi thường gặp vì học viên suy luận theo nghĩa tiếng Việt 'với', nhưng tiếng Anh chuẩn luôn dùng 'married to'." },
  { id: "a049", question: "The flight was delayed ___ three hours.", options: ["for", "by", "with", "of"], correctIndex: 1, explanation: "Giới từ 'by' ở đây diễn tả mức độ chênh lệch về thời gian hay số lượng, nghĩa là 'trễ đi một khoảng là bao nhiêu'. Câu này nói chuyến bay bị trễ mất ba tiếng nên 'by three hours' là cách diễn đạt đúng. 'For' sẽ sai vì 'for' chỉ dùng để nói về khoảng thời gian một hành động diễn ra, không phải mức độ trễ." },
  { id: "a050", question: "She has been working here ___ ten years.", options: ["since", "for", "during", "in"], correctIndex: 1, explanation: "'For' đi với khoảng thời gian kéo dài (for ten years), còn 'since' đi với mốc thời gian bắt đầu (since 2010). Câu này nêu độ dài mười năm nên 'for' là lựa chọn đúng. Nếu câu hỏi có mốc thời gian cụ thể như một năm hay một ngày, khi đó mới cần đổi sang 'since'." },
  { id: "a051", question: "He is ___ umbrella salesman.", options: ["a", "an", "the", "-"], correctIndex: 1, explanation: "'Umbrella' bắt đầu bằng âm nguyên âm /ʌ/, nên theo quy tắc mạo từ phải dùng 'an' thay vì 'a'. Đây là trường hợp âm thanh và chữ viết trùng khớp nên khá dễ nhận biết. Chọn 'a' sẽ nghe cấn và sai chính tả ngữ pháp vì hai âm nguyên âm liền nhau không tự nhiên khi phát âm." },
  { id: "a052", question: "She bought ___ uniform for the new job.", options: ["a", "an", "the", "-"], correctIndex: 0, explanation: "Mặc dù 'uniform' bắt đầu bằng chữ cái nguyên âm 'u', nó lại được phát âm là /juː-/, mang âm /j/ giống phụ âm, nên phải dùng 'a' chứ không phải 'an'. Đây là một ví dụ khác nhắc lại quy tắc: mạo từ dựa vào âm thanh, không dựa vào mặt chữ. Nhóm từ như 'uniform', 'university', 'useful' đều cần ghi nhớ để tránh chọn nhầm 'an'." },
  { id: "a053", question: "They went to ___ United States last summer.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Tên quốc gia có cấu trúc số nhiều hoặc chứa các từ như 'States', 'Kingdom', 'Republic' luôn cần 'the' đứng trước: the United States, the United Kingdom. Câu này nhắc đến nước Mỹ theo tên đầy đủ nên phải dùng 'the'. Đừng nhầm với các tên quốc gia thông thường như 'France' hay 'Vietnam', vốn không cần mạo từ." },
  { id: "a054", question: "I've always wanted to visit ___ Netherlands.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Những quốc gia có tên ở dạng số nhiều như Hà Lan (the Netherlands) hay Philippines (the Philippines) luôn cần 'the'. Câu này nói về mong muốn đến thăm Hà Lan nên chọn 'the' là chính xác. Đây là ngoại lệ so với đa số tên quốc gia không cần mạo từ, nên cần ghi nhớ riêng nhóm từ này." },
  { id: "a055", question: "He is studying ___ history at Cambridge.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên các môn học hoặc ngành học khi nói chung không cần mạo từ: history, physics, economics. Câu này nói về việc học lịch sử tại Cambridge theo nghĩa chung nên dùng zero article là đúng. Nếu thêm 'the' vào sẽ ngụ ý một môn lịch sử cụ thể đã được nhắc trước đó, không khớp với ngữ cảnh câu." },
  { id: "a056", question: "___ French are known for their cuisine.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Cấu trúc 'the + tính từ chỉ quốc tịch' (dạng số nhiều) dùng để chỉ cả một dân tộc, ví dụ 'the French' nghĩa là người Pháp nói chung. Câu này nói về đặc điểm ẩm thực của người Pháp nên 'the' là lựa chọn đúng. Không thể bỏ mạo từ ở đây vì tính từ quốc tịch cần 'the' đứng trước để mang nghĩa 'toàn thể người dân'." },
  { id: "a057", question: "She can speak ___ Chinese and ___ Japanese.", options: ["the/the", "a/a", "-/-", "the/-"], correctIndex: 2, explanation: "Tên các ngôn ngữ khi đứng một mình, không đi kèm từ 'language', không cần mạo từ: Chinese, Japanese, English. Câu này nói về khả năng nói được hai ngôn ngữ nên dùng zero article cho cả hai. Nếu thêm 'the' vào sẽ sai, vì 'the Chinese' lại mang nghĩa khác là 'người Trung Quốc' chứ không phải ngôn ngữ." },
  { id: "a058", question: "I'm going to ___ bed — it's late.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Cụm cố định 'go to bed' mang nghĩa chức năng là đi ngủ, không cần mạo từ, giống như 'go to school', 'go to work'. Câu này nói về việc chuẩn bị đi ngủ vì đã muộn nên dùng zero article. Nếu thêm 'the' ('go to the bed'), câu sẽ mang nghĩa khác là di chuyển đến vị trí cái giường, không phải hành động đi ngủ." },
  { id: "a059", question: "She spent two years in ___ prison for fraud.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Cụm 'in prison' không dùng mạo từ khi nói về việc ai đó đang là tù nhân, tức đang chịu án tù. Câu này nói cô ấy ngồi tù hai năm vì gian lận nên zero article là đúng. Ngược lại, nếu ai đó chỉ đến thăm nhà tù với tư cách khách (không phải tù nhân), câu sẽ là 'visit the prison', có mạo từ 'the' vì lúc đó nói về tòa nhà cụ thể." },
  { id: "a060", question: "They are at ___ work right now.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Cụm cố định 'at work' nghĩa là đang trong giờ làm việc, không cần mạo từ đứng trước. Câu này nói họ đang làm việc ngay lúc này nên zero article là chuẩn. Đây là một trong những cụm từ cố định cần học thuộc lòng vì không tuân theo quy tắc mạo từ thông thường." },
  { id: "a061", question: "___ Pacific Ocean is the largest ocean on Earth.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Tên các đại dương luôn đi kèm 'the': the Pacific Ocean, the Atlantic Ocean. Câu này nhắc đến đại dương lớn nhất thế giới nên 'the' là lựa chọn bắt buộc. Đây là quy tắc cố định cho loại danh từ riêng chỉ đại dương, tương tự như tên sông hay dãy núi." },
  { id: "a062", question: "We crossed ___ Alps on our road trip.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Tên các dãy núi gồm nhiều đỉnh luôn cần 'the': the Alps, the Himalayas, the Rocky Mountains. Câu này nói về việc băng qua dãy Alps nên 'the' là đáp án đúng. Cần phân biệt với tên một ngọn núi đơn lẻ như Mount Everest, vốn không cần mạo từ." },
  { id: "a063", question: "She is from ___ France.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên quốc gia thông thường không cần mạo từ: France, Japan, Vietnam. Câu này nói cô ấy đến từ Pháp nên dùng zero article là chính xác. Chỉ một số ít quốc gia đặc biệt như 'the USA' hay 'the UK' mới cần 'the', còn lại phần lớn tên nước đều không có mạo từ." },
  { id: "a064", question: "He visited ___ Cairo last spring.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên thành phố không cần mạo từ đứng trước: Cairo, Tokyo, London. Câu này nói về chuyến thăm Cairo vào mùa xuân trước nên zero article là đúng. Đây là quy tắc chung cho hầu hết tên riêng địa danh cấp thành phố." },
  { id: "a065", question: "Mount Fuji is in ___ Japan.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Giống như quy tắc với tên quốc gia thông thường, 'Japan' không cần mạo từ đứng trước. Câu này nói núi Phú Sĩ nằm ở Nhật Bản nên zero article là lựa chọn chuẩn. Đừng nhầm với các quốc gia đặc biệt cần 'the' như 'the Philippines' hay 'the Netherlands'." },
  { id: "a066", question: "The River Thames runs through ___ London.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên thành phố như 'London' không cần mạo từ, tương tự quy tắc đã áp dụng cho Cairo hay Tokyo. Câu này nói sông Thames chảy qua London nên zero article là đáp án đúng. Chỉ tên sông (the Thames) mới cần 'the', còn tên thành phố thì không." },
  { id: "a067", question: "There's ___ interesting story behind this painting.", options: ["a", "an", "the", "-"], correctIndex: 1, explanation: "'Interesting' bắt đầu bằng âm nguyên âm /ɪ/ nên cần 'an' đứng trước theo đúng quy tắc mạo từ. Câu này lần đầu nhắc đến câu chuyện đằng sau bức tranh nên chưa thể dùng 'the', vì người nghe chưa biết trước đó. Nếu chọn 'the' ở đây sẽ sai logic vì thông tin chưa được xác định trong ngữ cảnh trước đó." },
  { id: "a068", question: "___ story you told us was fascinating.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Khi câu chuyện đã được nhắc đến hoặc người nghe hiểu rõ câu chuyện nào đang được nói tới, ta dùng 'the' để chỉ vật đã xác định. Câu này nói về câu chuyện 'mà bạn vừa kể', nghĩa là đã được biết đến rõ ràng, nên 'the' là lựa chọn đúng. Nếu dùng 'a' sẽ sai vì lúc này câu chuyện không còn là thông tin mới, chưa xác định nữa." },
  { id: "a069", question: "Lions and tigers are ___ wild animals.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Khi nói về một loài/nhóm sự vật theo nghĩa khái quát chung, danh từ số nhiều không cần mạo từ: lions, tigers = sư tử, hổ nói chung. Câu này nói sư tử và hổ là động vật hoang dã nói chung nên zero article là đúng. Nếu thêm 'the' vào số nhiều này sẽ sai, vì 'the' chỉ dùng khi nói đến những cá thể cụ thể đã biết." },
  { id: "a070", question: "___ lion is the king of the jungle.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Cấu trúc 'the + danh từ số ít' có thể dùng để đại diện cho cả một loài, ví dụ 'the lion' nghĩa là loài sư tử nói chung, khác với câu trước dùng số nhiều không mạo từ. Câu này nói sư tử là chúa tể rừng xanh theo nghĩa đại diện cho cả loài nên 'the' là lựa chọn phù hợp. Đừng nhầm với cách dùng số nhiều không mạo từ ở câu 'Lions and tigers are wild animals' - đây là hai cách diễn đạt khác nhau cho cùng một ý khái quát." },
  { id: "a071", question: "She plays ___ violin in the school orchestra.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Tương tự quy tắc chơi nhạc cụ đã gặp ở câu về piano, tên nhạc cụ khi nói về việc chơi luôn đi với 'the': play the violin. Câu này nói cô ấy chơi violin trong dàn nhạc trường nên 'the' là đáp án đúng. Đây là quy tắc riêng cho nhạc cụ, khác với môn thể thao (play football - không mạo từ)." },
  { id: "a072", question: "Children need ___ love and ___ security.", options: ["the/the", "a/a", "-/-", "the/a"], correctIndex: 2, explanation: "Danh từ trừu tượng, không đếm được khi nói chung không cần mạo từ: love, security, happiness. Câu này nói trẻ em cần tình yêu thương và sự an toàn nói chung nên zero article là đúng cho cả hai từ. Nếu thêm 'the' hay 'a' vào sẽ sai vì các khái niệm này không được xác định cụ thể hay đếm được trong câu." },
  { id: "a073", question: "Money can't buy ___ happiness.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Danh từ trừu tượng khi nói chung, không nhắc đến một biểu hiện cụ thể nào, không cần mạo từ: happiness, love, freedom. Câu này nói tiền không mua được hạnh phúc theo nghĩa khái quát nên zero article là chính xác. Thêm 'the' vào sẽ sai vì không có ngữ cảnh nào xác định 'loại hạnh phúc' cụ thể đang được nhắc tới." },
  { id: "a074", question: "I usually have ___ lunch at 12:30.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Tên bữa ăn khi nói chung, không có tính từ mô tả kèm theo, không cần mạo từ, giống quy tắc đã gặp với 'breakfast'. Câu này nói thói quen ăn trưa lúc 12:30 nên zero article là đúng. Nếu thêm tính từ như 'a quick lunch', lúc đó mới cần mạo từ 'a'." },
  { id: "a075", question: "We had ___ fantastic lunch at that Italian restaurant.", options: ["a", "an", "the", "-"], correctIndex: 0, explanation: "Khi bữa ăn có tính từ đi kèm để miêu tả, khác với cách nói chung, ta cần thêm mạo từ: a fantastic lunch, a big breakfast. Câu này miêu tả bữa trưa tuyệt vời tại nhà hàng Ý nên cần 'a' đứng trước vì có tính từ 'fantastic' bổ nghĩa. Đây là điểm khác biệt quan trọng so với câu 'have lunch' thông thường không mạo từ." },
  { id: "a076", question: "I go to ___ school every day.", options: ["a", "an", "the", "-"], correctIndex: 3, explanation: "Cụm 'go to school' mang nghĩa chức năng là đi học, không cần mạo từ, tương tự 'go to bed', 'go to work'. Câu này nói về việc đi học mỗi ngày theo nghĩa hoạt động học tập nên zero article là đúng. Nếu dùng 'the' ('go to the school'), câu sẽ chuyển sang nghĩa đến tòa nhà trường vì lý do khác, không phải để học." },
  { id: "a077", question: "My parents visited ___ school last week to meet my teacher.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Khi nói đến tòa nhà hoặc cơ sở vật chất cụ thể của trường học, không phải chức năng học tập, ta cần dùng 'the'. Câu này nói bố mẹ đến trường để gặp giáo viên, tức là đến tòa nhà trường vì mục đích khác việc học, nên 'the' là lựa chọn đúng. Đây chính là điểm đối lập với câu 'go to school' (zero article) ở trên, giúp phân biệt hai cách dùng." },
  { id: "a078", question: "___ Sahara is the largest hot desert in the world.", options: ["A", "An", "The", "-"], correctIndex: 2, explanation: "Tên các sa mạc luôn đi kèm 'the': the Sahara, the Gobi, the Arabian Desert. Câu này nói về sa mạc nóng lớn nhất thế giới nên 'the' là đáp án chuẩn. Đây là quy tắc cố định cho loại địa danh này, tương tự tên sông, đại dương và dãy núi đã gặp ở các câu trước." },
  { id: "a079", question: "She is ___ best student in the class.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Mạo từ 'the' luôn đứng trước cấp so sánh cao nhất (superlative): the best, the biggest, the most intelligent. Câu này khen cô ấy là học sinh giỏi nhất lớp nên 'the' là lựa chọn bắt buộc. Không thể bỏ 'the' ở đây vì cấu trúc so sánh nhất luôn cần mạo từ xác định đi kèm." },
  { id: "a080", question: "This is ___ first time I've been to Italy.", options: ["a", "an", "the", "-"], correctIndex: 2, explanation: "Số thứ tự như 'the first', 'the second', 'the last' luôn cần 'the' đứng trước. Câu này nói đây là lần đầu tiên đến Ý nên 'the first' là cách diễn đạt chuẩn. Đây là quy tắc gần giống với cấp so sánh nhất, cả hai đều cần mạo từ xác định 'the' bắt buộc." },
  { id: "a081", question: "She works ___ the hospital near the city center.", options: ["in", "at", "on", "by"], correctIndex: 1, explanation: "Khi nói đến nơi làm việc theo nghĩa chức năng, giới từ 'at' thường được dùng: at the hospital, at the office, at school. Câu này nói về nơi cô ấy làm việc nên 'at' là lựa chọn phù hợp. 'In' vẫn có thể đúng trong một số ngữ cảnh khác, nhưng khi nhấn mạnh địa điểm làm việc cụ thể như một điểm mốc, 'at' tự nhiên hơn." },
  { id: "a082", question: "The company is based ___ Paris.", options: ["in", "at", "on", "by"], correctIndex: 0, explanation: "Với tên thành phố, quốc gia hay khu vực rộng, giới từ 'in' được dùng để chỉ vị trí: in Paris, in London. Câu này nói công ty đặt trụ sở tại Paris nên 'in' là đáp án đúng. 'At' thường chỉ dùng cho địa điểm cụ thể, nhỏ hơn như một tòa nhà hay một địa chỉ, không phù hợp với tên thành phố." },
  { id: "a083", question: "There are many fish ___ the river.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Giới từ 'in' dùng cho các vùng nước như sông, biển, hồ vì cá và các sinh vật khác nằm bên trong khối nước đó: in the river, in the sea. Câu này nói có nhiều cá trong sông nên 'in' là lựa chọn chính xác. 'On' sẽ sai vì cá không nằm trên bề mặt nước mà ở bên trong dòng nước." },
  { id: "a084", question: "She's sitting ___ the corner of the room.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Góc phòng được xem như một không gian bên trong nên dùng 'in': in the corner of the room. Câu này nói cô ấy ngồi ở góc phòng nên 'in' là đáp án đúng. Cần phân biệt với 'at the corner' (ở góc đường/ngã tư ngoài trời), nơi lại dùng giới từ 'at'." },
  { id: "a085", question: "He was standing ___ the corner of the street.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Ngược lại với góc phòng, góc đường ngoài trời được coi như một điểm mốc cụ thể nên dùng 'at': at the corner of the street. Câu này nói anh ấy đứng ở góc phố nên 'at' là lựa chọn chuẩn. Đừng nhầm với 'in the corner', chỉ dùng cho không gian trong nhà như góc phòng." },
  { id: "a086", question: "The café is ___ the corner of Main Street and Elm Avenue.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Khi chỉ vị trí giao nhau giữa hai con đường, giới từ 'at' được dùng theo cụm cố định 'at the corner of'. Câu này miêu tả quán cà phê nằm ở ngã tư hai con đường nên 'at' là đáp án đúng. Đây cùng quy tắc với câu trước về góc phố ngoài trời, khác với góc phòng dùng 'in'." },
  { id: "a087", question: "She lives ___ a small village ___ the mountains.", options: ["in/in", "at/in", "on/at", "in/at"], correctIndex: 0, explanation: "Giới từ 'in' dùng cho cả làng mạc, thành phố lẫn các vùng địa lý rộng như núi non: in a village, in the mountains. Câu này nói cô ấy sống trong một ngôi làng nhỏ nằm trên núi nên cả hai chỗ trống đều cần 'in'. Đây là quy tắc nhất quán: các khu vực có ranh giới bao quanh (làng, núi, thành phố) đều đi với 'in', không đổi giữa các giới từ khác." },
  { id: "a088", question: "The keys are ___ the drawer.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Giới từ 'in' dùng khi vật nằm bên trong một vật chứa có không gian kín: in the drawer, in the box. Câu này nói chìa khóa nằm trong ngăn kéo nên 'in' là lựa chọn đúng. 'On' sẽ sai vì ngăn kéo là không gian có thể đóng lại, khác với bề mặt phẳng như bàn hay sàn nhà." },
  { id: "a089", question: "He was waiting ___ the door.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Các điểm ra vào như cửa, cổng, cửa sổ thường đi với giới từ 'at' vì được xem như một điểm mốc: at the door, at the gate. Câu này nói anh ấy đứng chờ ở cửa nên 'at' là đáp án chính xác. 'In' sẽ sai vì cửa không phải là không gian để đứng 'bên trong'." },
  { id: "a090", question: "She saw her name ___ the list.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Danh sách, thực đơn, chương trình nghị sự luôn đi với giới từ 'on': on the list, on the menu, on the agenda. Câu này nói cô ấy thấy tên mình trên danh sách nên 'on' là lựa chọn đúng. 'In' là lỗi phổ biến cần tránh vì các cụm từ liên quan đến danh sách đều cố định dùng 'on'." },
  { id: "a091", question: "The map is ___ the wall in the corridor.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Nhắc lại quy tắc bề mặt thẳng đứng: giới từ 'on' dùng cho tường, trần nhà: on the wall, on the ceiling. Câu này nói tấm bản đồ được treo trên tường hành lang nên 'on' là đáp án đúng. 'In' không phù hợp vì tấm bản đồ chỉ tiếp xúc bề mặt tường, không nằm bên trong bức tường." },
  { id: "a092", question: "The dog was lying ___ the floor.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Sàn nhà cũng là một bề mặt nằm ngang nên dùng giới từ 'on': on the floor, on the ground. Câu này nói con chó đang nằm trên sàn nên 'on' là lựa chọn chính xác. 'In' sẽ sai vì sàn nhà không phải là không gian kín để nằm 'bên trong'." },
  { id: "a093", question: "They live ___ the suburbs.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Các khu vực địa lý rộng như ngoại ô, nông thôn, thành phố đi với giới từ 'in': in the suburbs, in the countryside. Câu này nói họ sống ở khu ngoại ô nên 'in' là đáp án đúng. 'At' không phù hợp vì khu vực này quá rộng để coi là một điểm mốc cụ thể." },
  { id: "a094", question: "He is ___ the phone right now — call back later.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Cụm cố định 'on the phone' nghĩa là đang nói chuyện điện thoại, luôn dùng giới từ 'on'. Câu này nói anh ấy đang bận nghe điện thoại nên 'on' là lựa chọn chuẩn. Học thuộc cụm này cùng với 'on TV', 'on the radio' sẽ giúp tránh nhầm sang 'in' hay 'at'." },
  { id: "a095", question: "She saw the advertisement ___ TV.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Các phương tiện truyền thông như truyền hình, đài phát thanh, internet đều đi với giới từ 'on': on TV, on the radio, on the internet. Câu này nói thấy quảng cáo trên tivi nên 'on' là đáp án đúng. Đây là nhóm cụm từ cố định cần ghi nhớ chung với 'on the phone' đã gặp ở câu trước." },
  { id: "a096", question: "He read about it ___ the newspaper.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Các ấn phẩm in như báo, sách, tạp chí lại dùng giới từ 'in' chứ không phải 'on': in the newspaper, in a book, in a magazine. Câu này nói đọc được thông tin trên báo nên 'in' là lựa chọn đúng. Đây là điểm dễ nhầm với nhóm phương tiện truyền thông điện tử (on TV, on the radio) vừa học ở câu trước, vì hai nhóm này dùng giới từ khác nhau." },
  { id: "a097", question: "The plane is flying ___ the clouds.", options: ["above", "over", "below", "under"], correctIndex: 1, explanation: "'Over' diễn tả chuyển động vượt qua phía trên một vật gì đó, phù hợp khi máy bay đang bay xuyên qua/trên các đám mây. Câu này miêu tả máy bay đang di chuyển nên 'over' hợp lý hơn 'above'. 'Above' thường chỉ vị trí tĩnh ở phía trên mà không nhấn mạnh chuyển động, nên ít tự nhiên hơn trong câu này." },
  { id: "a098", question: "There's a lamp hanging ___ the dining table.", options: ["above", "over", "below", "under"], correctIndex: 0, explanation: "'Above' diễn tả vị trí tĩnh ở phía trên một vật, không nhất thiết phải chuyển động hay tiếp xúc trực tiếp. Câu này nói chiếc đèn treo phía trên bàn ăn, một vị trí cố định, nên 'above' là lựa chọn phù hợp. 'Over' thường nhấn mạnh chuyển động hoặc sự bao phủ, ít dùng cho vị trí tĩnh như đèn treo cố định thế này." },
  { id: "a099", question: "The temperature is ___ zero today.", options: ["above", "over", "below", "under"], correctIndex: 2, explanation: "'Below' dùng để chỉ mức độ hoặc vị trí thấp hơn một mốc nào đó, thường dùng với nhiệt độ, số liệu: below zero, below average. Câu này nói nhiệt độ hôm nay thấp hơn 0 độ nên 'below' là đáp án đúng. 'Under' tuy gần nghĩa nhưng thường dùng cho vị trí vật lý cụ thể (dưới gầm bàn), không tự nhiên khi nói về mức nhiệt độ." },
  { id: "a100", question: "The cat jumped ___ the fence.", options: ["above", "over", "below", "under"], correctIndex: 1, explanation: "'Over' diễn tả chuyển động vượt qua một chướng ngại vật từ bên này sang bên kia: jump over, climb over. Câu này nói con mèo nhảy qua hàng rào nên 'over' là lựa chọn chính xác. 'Above' sẽ sai vì chỉ diễn tả vị trí, không diễn tả được hành động vượt qua như động từ 'jump' đòi hỏi." },
  { id: "a101", question: "The children were swimming ___ the bridge.", options: ["above", "over", "below", "under"], correctIndex: 3, explanation: "'Under' diễn tả vị trí ở ngay bên dưới một vật, ở đây là bên dưới gầm cầu. Câu này nói bọn trẻ đang bơi ngay dưới gầm cầu nên 'under' là đáp án đúng. 'Below' tuy cùng nghĩa 'thấp hơn' nhưng thường dùng cho khoảng cách xa hơn hoặc mức độ, không tự nhiên bằng 'under' khi nói về vị trí vật lý sát gần như gầm cầu." },
  { id: "a102", question: "She walked ___ the park to get to the office.", options: ["through", "across", "along", "past"], correctIndex: 0, explanation: "'Through' diễn tả việc di chuyển xuyên qua bên trong một không gian có ranh giới bao quanh như công viên, đường hầm. Câu này nói cô ấy đi xuyên qua công viên để đến văn phòng nên 'through' là lựa chọn đúng. 'Across' dễ bị nhầm nhưng 'across' thường dùng cho việc băng qua một bề mặt phẳng như đường phố, không phải đi xuyên qua một không gian rộng có ranh giới." },
  { id: "a103", question: "We drove ___ a small village without stopping.", options: ["through", "across", "along", "past"], correctIndex: 3, explanation: "'Past' diễn tả việc đi ngang qua một vị trí mà không dừng lại. Câu này nói họ lái xe đi ngang qua một ngôi làng nhỏ mà không dừng nên 'past' là đáp án đúng. 'Through' sẽ khác nghĩa vì ngụ ý đi xuyên vào bên trong ngôi làng, trong khi câu này chỉ đơn thuần đi ngang qua bên ngoài." },
  { id: "a104", question: "She swam ___ the river.", options: ["through", "across", "along", "past"], correctIndex: 1, explanation: "'Across' diễn tả việc di chuyển từ bờ bên này sang bờ bên kia của một bề mặt như sông, đường. Câu này nói cô ấy bơi từ bờ này sang bờ kia của con sông nên 'across' là lựa chọn chính xác. 'Through' sẽ sai vì ngụ ý bơi xuyên vào bên trong dòng nước theo chiều dài, không phải băng ngang qua bề rộng của sông." },
  { id: "a105", question: "He walked ___ the beach for an hour.", options: ["through", "across", "along", "past"], correctIndex: 2, explanation: "'Along' diễn tả việc di chuyển song song theo chiều dài của một con đường, bờ biển: walk along the beach/road. Câu này nói anh ấy đi dạo dọc theo bờ biển trong một tiếng nên 'along' là đáp án đúng. 'Across' sẽ sai vì đó là băng ngang qua chiều rộng, không phải đi dọc theo chiều dài như câu này diễn tả." },
  { id: "a106", question: "She ran ___ the building and didn't stop.", options: ["through", "across", "past", "along"], correctIndex: 2, explanation: "'Past' diễn tả việc chạy ngang qua một vị trí mà không dừng lại hay đi vào bên trong. Câu này nói cô ấy chạy qua tòa nhà mà không dừng nên 'past' là lựa chọn đúng. 'Through' sẽ sai vì ngụ ý chạy xuyên vào bên trong tòa nhà, khác hẳn với việc chạy ngang qua bên ngoài như câu này mô tả." },
  { id: "a107", question: "The cat crawled ___ the fence into the garden.", options: ["through", "across", "over", "past"], correctIndex: 0, explanation: "'Through' dùng khi chui qua một khe hở hoặc lỗ hổng của một vật, ở đây là qua khe của hàng rào. Câu này nói con mèo chui qua hàng rào để vào vườn nên 'through' là đáp án chính xác. 'Over' sẽ sai vì đó là hành động nhảy/trèo qua phía trên, khác với việc chui qua khe hở như 'crawl' diễn tả." },
  { id: "a108", question: "They drove ___ the Alps to reach Italy.", options: ["through", "across", "over", "past"], correctIndex: 2, explanation: "'Over' dùng khi vượt qua địa hình cao như núi, đèo bằng một chuyển động đi qua phía trên. Câu này nói họ lái xe vượt dãy Alps để đến Ý nên 'over' là lựa chọn đúng. 'Through' sẽ sai vì ngụ ý đi xuyên vào lòng núi (như qua đường hầm), không phải vượt qua từ trên các đỉnh núi." },
  { id: "a109", question: "She walked ___ the street to buy a coffee.", options: ["along", "across", "through", "past"], correctIndex: 1, explanation: "'Across' dùng khi băng ngang qua một con đường, từ vỉa hè bên này sang bên kia. Câu này nói cô ấy băng qua đường để mua cà phê nên 'across' là đáp án đúng. 'Along' sẽ sai vì đó là đi dọc theo chiều dài con đường, không phải băng ngang qua bề rộng của nó." },
  { id: "a110", question: "He jumped ___ the puddle to avoid getting his shoes wet.", options: ["across", "over", "through", "past"], correctIndex: 1, explanation: "'Over' dùng khi nhảy qua một chướng ngại vật nhỏ để tránh, ở đây là vũng nước. Câu này nói anh ấy nhảy qua vũng nước để không bị ướt giày nên 'over' là lựa chọn chính xác. 'Across' ít tự nhiên hơn ở đây vì thường dùng cho bề mặt rộng cần băng qua, không phải một vật cản nhỏ cần nhảy qua như vũng nước." },
  { id: "a111", question: "She is going ___ school now.", options: ["to", "at", "in", "for"], correctIndex: 0, explanation: "Giới từ 'to' diễn tả chuyển động hướng đến một địa điểm: go to school, travel to Paris. Câu này nói cô ấy đang trên đường đến trường nên 'to' là đáp án đúng. 'At' sẽ sai vì 'at' chỉ vị trí tĩnh tại một nơi, không diễn tả được chuyển động hướng tới như động từ 'go' đòi hỏi." },
  { id: "a112", question: "He came ___ home late last night.", options: ["to", "at", "from", "-"], correctIndex: 3, explanation: "Từ 'home' khi dùng như trạng từ chỉ phương hướng (về nhà) không cần giới từ 'to' đứng trước: come home, go home. Câu này nói anh ấy về nhà muộn nên không thêm 'to' vào trước 'home'. Đây là ngoại lệ đặc biệt cần nhớ vì hầu hết các địa điểm khác đều cần 'to' khi đi kèm động từ chỉ chuyển động như 'go' hay 'come'." },
  { id: "a113", question: "They flew ___ London ___ New York.", options: ["to/from", "from/to", "in/to", "at/from"], correctIndex: 1, explanation: "Cặp giới từ 'from...to...' luôn đi cùng nhau để diễn tả điểm xuất phát và điểm đến của một chuyến đi. Câu này nói chuyến bay từ London đến New York nên đáp án đúng là 'from/to'. Đảo ngược thứ tự hai giới từ này sẽ làm sai nghĩa của câu vì 'from' luôn đứng trước điểm khởi hành." },
  { id: "a114", question: "She took the book ___ the shelf.", options: ["from", "off", "out of", "away from"], correctIndex: 1, explanation: "'Off' diễn tả việc lấy một vật ra khỏi một bề mặt mà nó đang tiếp xúc, ở đây là mặt giá sách. Câu này nói cô ấy lấy quyển sách từ trên kệ nên 'off' là lựa chọn đúng. 'From' cũng có thể chấp nhận được trong một số ngữ cảnh, nhưng 'off the shelf' là cách diễn đạt tự nhiên và phổ biến hơn khi nhấn mạnh việc tách vật ra khỏi bề mặt." },
  { id: "a115", question: "He pulled a rabbit ___ the hat.", options: ["from", "out of", "off", "into"], correctIndex: 1, explanation: "'Out of' diễn tả việc lấy một vật ra khỏi bên trong một không gian kín, ở đây là bên trong chiếc mũ. Câu này nói kéo con thỏ ra khỏi mũ nên 'out of' là đáp án chính xác. 'From' quá chung chung và không nhấn mạnh được việc vật đó đã ở bên trong trước khi được lấy ra như 'out of' thể hiện." },
  { id: "a116", question: "She walked ___ the room without saying a word.", options: ["into", "out of", "through", "past"], correctIndex: 1, explanation: "'Out of' diễn tả việc đi ra khỏi bên trong một không gian kín như căn phòng, tòa nhà. Câu này nói cô ấy bước ra khỏi phòng mà không nói gì nên 'out of' là lựa chọn đúng. 'Into' sẽ mang nghĩa ngược lại hoàn toàn, là đi vào bên trong chứ không phải đi ra." },
  { id: "a117", question: "He rushed ___ the building when the alarm went off.", options: ["into", "out of", "through", "past"], correctIndex: 1, explanation: "Tương tự câu trước, 'out of' diễn tả việc thoát ra khỏi bên trong một không gian. Câu này nói mọi người vội vã chạy ra khỏi tòa nhà khi có báo động nên 'out of' là đáp án đúng. 'Into' sẽ sai vì mang nghĩa ngược lại, là chạy vào bên trong tòa nhà thay vì thoát ra." },
  { id: "a118", question: "The cat jumped ___ the box.", options: ["into", "out of", "through", "onto"], correctIndex: 3, explanation: "'Onto' diễn tả chuyển động nhảy lên và đáp xuống bề mặt phía trên của một vật. Câu này nói con mèo nhảy lên trên chiếc hộp nên 'onto' là lựa chọn chính xác. 'Into' sẽ sai nghĩa vì đó là nhảy vào bên trong hộp (như hộp không có nắp và mèo lọt hẳn vào trong), khác với việc đứng trên bề mặt hộp." },
  { id: "a119", question: "She drove ___ the garage.", options: ["into", "out of", "through", "past"], correctIndex: 0, explanation: "'Into' diễn tả chuyển động đi vào bên trong một không gian kín như nhà để xe. Câu này nói cô ấy lái xe vào trong ga-ra nên 'into' là đáp án đúng. 'Out of' sẽ mang nghĩa ngược lại là đi ra khỏi, không phù hợp với hành động lái xe vào của câu này." },
  { id: "a120", question: "He walked ___ the crowd to reach the stage.", options: ["through", "across", "along", "past"], correctIndex: 0, explanation: "'Through' diễn tả việc di chuyển xuyên qua giữa một đám đông hoặc một khối vật cản dày đặc. Câu này nói anh ấy len qua đám đông để đến sân khấu nên 'through' là lựa chọn đúng. 'Past' sẽ sai vì đó là đi ngang qua bên cạnh mà không xuyên vào giữa, không phù hợp với việc len lỏi giữa đám đông đông đúc." },
  { id: "a121", question: "She is proud ___ her children's achievements.", options: ["of", "about", "for", "in"], correctIndex: 0, explanation: "Cụm tính từ cố định 'proud of + danh từ/đại từ' nghĩa là tự hào về ai/điều gì. Câu này nói tự hào về thành tích của con cái nên 'of' là giới từ đúng. 'About' là lựa chọn hay bị nhầm nhưng 'proud' luôn đi với 'of' theo cách dùng chuẩn." },
  { id: "a122", question: "He's angry ___ being left out of the meeting.", options: ["at", "about", "for", "of"], correctIndex: 1, explanation: "Cụm tính từ cố định 'angry about + V-ing/danh từ' nghĩa là tức giận vì điều gì xảy ra. Câu này nói tức giận vì bị bỏ ra khỏi cuộc họp nên 'about' là giới từ đúng. 'At' cũng có thể dùng khi đối tượng tức giận là một người cụ thể, nhưng với một sự việc/hành động như ở đây, 'about' tự nhiên hơn." },
  { id: "a123", question: "She is excited ___ the upcoming trip.", options: ["for", "at", "about", "of"], correctIndex: 2, explanation: "Cụm tính từ cố định 'excited about + danh từ/V-ing' nghĩa là hào hứng với điều gì. Câu này nói hào hứng về chuyến đi sắp tới nên 'about' là giới từ chuẩn. 'For' là lỗi phổ biến cần tránh, vì 'excited' không đi cùng 'for' theo cách dùng thông thường." },
  { id: "a124", question: "He is capable ___ doing much better.", options: ["for", "of", "in", "at"], correctIndex: 1, explanation: "Cụm tính từ cố định 'capable of + V-ing/danh từ' nghĩa là có khả năng làm điều gì. Câu này nói anh ấy có khả năng làm tốt hơn nhiều nên 'of' là giới từ đúng. 'For' dễ gây nhầm lẫn nhưng 'capable' luôn cần đi với 'of'." },
  { id: "a125", question: "She is worried ___ the test results.", options: ["for", "of", "about", "at"], correctIndex: 2, explanation: "Cụm tính từ cố định 'worried about + danh từ/V-ing' nghĩa là lo lắng về điều gì. Câu này nói lo lắng về kết quả bài kiểm tra nên 'about' là giới từ chuẩn. 'Of' là lựa chọn sai thường gặp vì học viên nhầm sang cấu trúc gần giống 'afraid of'." },
  { id: "a126", question: "He is different ___ his brother in many ways.", options: ["from", "to", "than", "with"], correctIndex: 0, explanation: "Cụm tính từ cố định 'different from + danh từ' nghĩa là khác biệt so với ai/điều gì, đây là cách dùng chuẩn mực và phổ biến nhất trong tiếng Anh Mỹ. Câu này so sánh anh ấy với anh trai mình ở nhiều điểm nên 'from' là giới từ được chọn. 'Than' đôi khi cũng được dùng không chính thức nhưng 'from' vẫn là lựa chọn an toàn và chuẩn xác hơn trong văn viết." },
  { id: "a127", question: "She is familiar ___ this area — she grew up here.", options: ["with", "to", "for", "of"], correctIndex: 0, explanation: "Cụm tính từ cố định 'familiar with + danh từ' nghĩa là quen thuộc với điều gì. Câu này nói cô ấy quen thuộc với khu vực này vì lớn lên ở đây nên 'with' là giới từ đúng. 'To' là lỗi cần tránh vì 'familiar' không đi cùng giới từ này." },
  { id: "a128", question: "I'm not satisfied ___ this result.", options: ["of", "about", "with", "at"], correctIndex: 2, explanation: "Cụm tính từ cố định 'satisfied with + danh từ/đại từ' nghĩa là hài lòng với điều gì. Câu này nói không hài lòng với kết quả này nên 'with' là giới từ chuẩn. 'About' là lựa chọn hay gây nhầm lẫn nhưng 'satisfied' cần đi cùng 'with'." },
  { id: "a129", question: "He is aware ___ the risks involved.", options: ["of", "about", "for", "with"], correctIndex: 0, explanation: "Cụm tính từ cố định 'aware of + danh từ/V-ing' nghĩa là nhận thức được/biết rõ về điều gì. Câu này nói nhận thức được các rủi ro liên quan nên 'of' là giới từ đúng. 'About' dễ bị chọn nhầm nhưng 'aware' luôn đi cùng 'of'." },
  { id: "a130", question: "She is keen ___ learning new languages.", options: ["at", "in", "on", "for"], correctIndex: 2, explanation: "Cụm tính từ cố định 'keen on + V-ing/danh từ' nghĩa là say mê/rất thích điều gì. Câu này nói rất thích học các ngôn ngữ mới nên 'on' là giới từ chuẩn. 'In' là lỗi phổ biến cần tránh vì 'keen' không đi cùng giới từ này." },
  { id: "a131", question: "They are committed ___ reducing carbon emissions.", options: ["for", "to", "in", "about"], correctIndex: 1, explanation: "Cụm tính từ cố định 'committed to + V-ing/danh từ' nghĩa là cam kết/tận tâm với điều gì. Câu này nói cam kết giảm phát thải carbon nên 'to' là giới từ đúng, lưu ý 'to' ở đây là giới từ nên theo sau bởi V-ing chứ không phải động từ nguyên mẫu. 'For' là lựa chọn sai thường gặp vì 'committed' không đi cùng giới từ này." },
  { id: "a132", question: "He is used ___ working long hours.", options: ["to", "of", "for", "at"], correctIndex: 0, explanation: "Cụm tính từ cố định 'used to + V-ing' nghĩa là quen với việc gì, cần phân biệt rõ với cấu trúc 'used to + V nguyên thể' diễn tả thói quen trong quá khứ đã không còn nữa. Câu này nói quen với việc làm việc nhiều giờ nên 'to' đi cùng V-ing (working) là đúng. Đây là điểm ngữ pháp dễ gây nhầm lẫn nhất trong nhóm này vì cùng một cụm từ nhưng mang hai chức năng ngữ pháp khác nhau." },
  { id: "a133", question: "She is dedicated ___ helping others.", options: ["for", "about", "to", "in"], correctIndex: 2, explanation: "Cụm tính từ cố định 'dedicated to + V-ing/danh từ' nghĩa là tận tâm/cống hiến cho điều gì. Câu này nói tận tâm giúp đỡ người khác nên 'to' là giới từ chuẩn. 'For' là lỗi thường gặp cần tránh vì 'dedicated' không đi cùng giới từ đó." },
  { id: "a134", question: "He is tired ___ hearing the same complaints every day.", options: ["from", "of", "with", "for"], correctIndex: 1, explanation: "Cụm tính từ cố định 'tired of + V-ing/danh từ' nghĩa là mệt mỏi/chán ngán với điều gì lặp đi lặp lại. Câu này nói mệt mỏi vì phải nghe những lời phàn nàn giống nhau mỗi ngày nên 'of' là giới từ đúng. 'With' hay bị chọn nhầm nhưng 'tired' theo nghĩa chán nản luôn cần 'of'." },
  { id: "a135", question: "She is famous ___ her beautiful paintings.", options: ["for", "of", "by", "as"], correctIndex: 0, explanation: "Cụm tính từ cố định 'famous for + danh từ/V-ing' nghĩa là nổi tiếng vì điều gì. Câu này nói nổi tiếng nhờ những bức tranh đẹp nên 'for' là giới từ chuẩn. 'By' là lựa chọn sai phổ biến vì 'famous' không đi cùng giới từ này." },
  { id: "a136", question: "He insisted ___ paying for the meal.", options: ["in", "about", "on", "for"], correctIndex: 2, explanation: "Cụm động từ cố định 'insist on + V-ing/danh từ' nghĩa là khăng khăng/kiên quyết làm điều gì. Câu này nói khăng khăng đòi trả tiền bữa ăn nên 'on' là giới từ đúng. 'In' là lỗi thường gặp cần tránh vì 'insist' luôn đi cùng 'on'." },
  { id: "a137", question: "She specializes ___ international tax law.", options: ["at", "in", "on", "for"], correctIndex: 1, explanation: "Cụm động từ cố định 'specialize in + danh từ' nghĩa là chuyên về một lĩnh vực nào đó. Câu này nói chuyên về luật thuế quốc tế nên 'in' là giới từ chuẩn. 'At' là lựa chọn sai thường gặp vì 'specialize' không đi cùng giới từ đó." },
  { id: "a138", question: "The team consists ___ twelve members.", options: ["of", "with", "from", "in"], correctIndex: 0, explanation: "Cụm động từ cố định 'consist of + danh từ' nghĩa là bao gồm/gồm có những thành phần nào. Câu này nói đội gồm mười hai thành viên nên 'of' là giới từ đúng. 'With' là lỗi cần tránh vì 'consist' luôn đi cùng 'of', không phải 'with'." },
  { id: "a139", question: "He suffers ___ severe migraines.", options: ["from", "of", "with", "about"], correctIndex: 0, explanation: "Cụm động từ cố định 'suffer from + tên bệnh/tình trạng' nghĩa là mắc phải/chịu đựng một căn bệnh hay tình trạng nào đó. Câu này nói anh ấy bị đau nửa đầu nặng nên 'from' là giới từ chuẩn. 'Of' là lựa chọn sai thường gặp vì 'suffer' theo nghĩa này luôn cần 'from'." },
  { id: "a140", question: "She applied ___ a scholarship last month.", options: ["at", "to", "for", "in"], correctIndex: 2, explanation: "Cụm động từ cố định 'apply for + vị trí/học bổng' nghĩa là đăng ký/nộp đơn xin điều gì, khác với 'apply to + tổ chức' nghĩa là nộp đơn vào một cơ quan/trường học. Câu này nói xin học bổng tháng trước nên 'for' là giới từ đúng vì đối tượng là học bổng, không phải tổ chức. Nhầm lẫn hai giới từ này là lỗi rất phổ biến nên cần ghi nhớ rõ sự khác biệt." },
  { id: "a141", question: "He congratulated her ___ winning the award.", options: ["for", "on", "about", "with"], correctIndex: 1, explanation: "Cụm động từ cố định 'congratulate someone on + V-ing/danh từ' nghĩa là chúc mừng ai về điều gì. Câu này nói chúc mừng cô ấy vì đã giành được giải thưởng nên 'on' là giới từ đúng. 'For' là lỗi thường gặp cần tránh vì 'congratulate' luôn đi cùng 'on'." },
  { id: "a142", question: "She blamed him ___ the accident.", options: ["for", "of", "about", "on"], correctIndex: 0, explanation: "Cụm động từ cố định 'blame someone for + danh từ/V-ing' nghĩa là đổ lỗi cho ai về điều gì. Câu này nói đổ lỗi cho anh ta về vụ tai nạn nên 'for' là giới từ chuẩn. 'Of' là lựa chọn sai thường gặp vì 'blame' không đi cùng giới từ này." },
  { id: "a143", question: "He believed ___ the power of positive thinking.", options: ["at", "in", "on", "about"], correctIndex: 1, explanation: "Cụm động từ cố định 'believe in + danh từ' nghĩa là tin vào một điều gì đó có tồn tại hoặc có giá trị, khác với 'believe + mệnh đề that' không cần giới từ. Câu này nói tin vào sức mạnh của tư duy tích cực nên 'in' là giới từ đúng. 'At' là lựa chọn sai vì 'believe' không bao giờ đi cùng giới từ đó." },
  { id: "a144", question: "She cares deeply ___ the environment.", options: ["of", "for", "about", "with"], correctIndex: 2, explanation: "Cụm động từ cố định 'care about + danh từ' nghĩa là quan tâm sâu sắc đến điều gì, cần phân biệt với 'care for' nghĩa là chăm sóc. Câu này nói quan tâm sâu sắc đến môi trường nên 'about' là giới từ đúng. Nếu dùng 'for' ở đây sẽ đổi nghĩa thành 'chăm sóc môi trường' theo cách chăm nom trực tiếp, không khớp hoàn toàn với ý 'quan tâm' của câu." },
  { id: "a145", question: "He was accused ___ stealing the documents.", options: ["for", "with", "of", "about"], correctIndex: 2, explanation: "Cụm động từ cố định 'accuse someone of + V-ing/danh từ' nghĩa là buộc tội ai về điều gì. Câu này nói bị buộc tội đánh cắp tài liệu nên 'of' là giới từ chuẩn. 'With' là lựa chọn sai thường gặp vì 'accuse' luôn đi cùng 'of'." },
  { id: "a146", question: "I'll meet you ___ noon tomorrow.", options: ["in", "on", "at", "by"], correctIndex: 2, explanation: "Nhắc lại quy tắc thời điểm cụ thể trong ngày luôn dùng 'at': at noon, at midnight, at dawn. Câu này hẹn gặp nhau lúc trưa ngày mai nên 'at' là đáp án đúng. 'In' hay 'on' đều không phù hợp với mốc giờ cụ thể như thế này." },
  { id: "a147", question: "They got married ___ Christmas Day.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Ngày lễ cụ thể cũng được xem như một 'ngày' nên đi với giới từ 'on': on Christmas Day, on New Year's Day. Câu này nói họ kết hôn vào ngày Giáng sinh nên 'on' là lựa chọn đúng. 'In' sẽ sai vì giới từ đó chỉ dùng cho khoảng thời gian rộng hơn như tháng hay năm, không phải một ngày cụ thể." },
  { id: "a148", question: "I'll finish this ___ the end of the month.", options: ["in", "on", "at", "by"], correctIndex: 3, explanation: "'By' mang nghĩa hạn chót, không muộn hơn một thời điểm nhất định. Câu này nói sẽ hoàn thành trước cuối tháng nên 'by' là đáp án đúng. 'At' sẽ sai vì không diễn tả được ý nghĩa 'trước hoặc đúng lúc', chỉ đơn thuần chỉ một thời điểm." },
  { id: "a149", question: "She was reading ___ the night.", options: ["in", "during", "at", "on"], correctIndex: 1, explanation: "'During' dùng để chỉ một khoảng thời gian cụ thể mà một hành động diễn ra bên trong đó, ở đây là suốt đêm. Câu này nói cô ấy đọc sách vào ban đêm nên 'during' là lựa chọn phù hợp. 'At' cũng có thể đi với 'night' (at night) trong ngữ cảnh khác, nhưng khi nhấn mạnh 'trong suốt khoảng thời gian đó', 'during the night' tự nhiên hơn." },
  { id: "a150", question: "He worked here ___ 1990 ___ 2005.", options: ["from/to", "since/until", "for/until", "from/until"], correctIndex: 0, explanation: "Cặp giới từ 'from...to...' diễn tả khoảng thời gian từ điểm bắt đầu đến điểm kết thúc. Câu này nói làm việc từ năm 1990 đến năm 2005 nên 'from/to' là đáp án đúng. 'Since/until' cũng diễn tả ý tương tự nhưng thường dùng khi khoảng thời gian đó kéo dài liên tục đến hiện tại hoặc một mốc xác định khác, không phù hợp bằng 'from...to' khi cả hai mốc đều đã kết thúc trong quá khứ." },
  { id: "a151", question: "She has been studying ___ this morning.", options: ["since", "for", "during", "in"], correctIndex: 0, explanation: "'Since' dùng với một mốc thời gian cụ thể đánh dấu điểm bắt đầu của hành động, thường đi cùng thì hiện tại hoàn thành. Câu này nói đã học từ sáng đến giờ nên 'since' là lựa chọn đúng. 'For' sẽ sai vì giới từ đó chỉ dùng với khoảng thời gian (for two hours), không phải mốc thời gian cụ thể như 'this morning'." },
  { id: "a152", question: "They argued ___ an hour before reaching an agreement.", options: ["since", "for", "during", "in"], correctIndex: 1, explanation: "'For' dùng với khoảng thời gian kéo dài của một hành động, ở đây là một tiếng đồng hồ tranh cãi. Câu này nói họ tranh cãi trong một tiếng trước khi đạt thỏa thuận nên 'for' là đáp án đúng. 'Since' sẽ sai vì giới từ đó cần đi với mốc thời gian bắt đầu cụ thể, không phải độ dài thời gian." },
  { id: "a153", question: "She waited ___ the bus ___ half an hour.", options: ["for/during", "for/for", "until/for", "during/for"], correctIndex: 1, explanation: "Ô trống đầu là cụm cố định 'wait for + danh từ' (chờ xe buýt), ô trống sau là 'for + khoảng thời gian' (nửa tiếng đồng hồ chờ đợi). Câu này cần cả hai giới từ đều là 'for' vì phục vụ hai chức năng khác nhau nhưng cùng dùng một giới từ. Đừng nhầm ô thứ hai sang 'during', vì 'during' cần đi với một sự kiện/danh từ xác định (during the meeting), không phải một con số thời lượng như 'half an hour'." },
  { id: "a154", question: "He'll stay here ___ Monday.", options: ["until", "by", "for", "since"], correctIndex: 0, explanation: "'Until' diễn tả một hành động tiếp diễn liên tục cho đến khi đạt tới một thời điểm nào đó. Câu này nói anh ấy sẽ ở lại đây đến hết thứ Hai nên 'until' là lựa chọn đúng vì nhấn mạnh việc lưu trú kéo dài. 'By' sẽ mang nghĩa khác, là hoàn thành một việc gì đó không muộn hơn một mốc, không diễn tả được sự tiếp diễn như 'stay'." },
  { id: "a155", question: "Please have the report ready ___ 9 AM tomorrow.", options: ["until", "by", "for", "since"], correctIndex: 1, explanation: "'By' dùng cho hạn chót của một trạng thái/hành động cần hoàn tất, nghĩa là không muộn hơn thời điểm đó. Câu này nói báo cáo cần sẵn sàng trước 9 giờ sáng nên 'by' là đáp án đúng. 'Until' sẽ sai vì đó diễn tả một hành động kéo dài liên tục, trong khi 'have ready' là một trạng thái hoàn thành tại một mốc, phù hợp với 'by' hơn." },
  { id: "a156", question: "She was nervous ___ the exam.", options: ["before", "during", "after", "for"], correctIndex: 1, explanation: "'During' dùng để chỉ một sự kiện có khoảng thời gian xác định mà cảm xúc hay hành động diễn ra bên trong đó. Câu này nói cô ấy lo lắng trong suốt kỳ thi nên 'during' là lựa chọn đúng. 'Before' sẽ đổi nghĩa thành lo lắng trước khi thi diễn ra, không khớp với ý 'trong lúc thi' của câu." },
  { id: "a157", question: "I'm tired — I've been working ___ 7 AM.", options: ["since", "for", "during", "from"], correctIndex: 0, explanation: "'Since' đi cùng thì hiện tại hoàn thành để chỉ mốc thời gian bắt đầu của một hành động còn tiếp diễn đến hiện tại. Câu này nói đã làm việc từ 7 giờ sáng đến giờ nên 'since' là đáp án đúng. 'For' sẽ sai vì đó cần đi với khoảng thời gian (for X hours), không phải một mốc giờ cụ thể như '7 AM'." },
  { id: "a158", question: "They haven't spoken to each other ___ months.", options: ["since", "for", "during", "in"], correctIndex: 1, explanation: "'For' dùng với khoảng thời gian đã trôi qua, ở đây là 'nhiều tháng' không nói chuyện với nhau. Câu này ở thì hiện tại hoàn thành phủ định nên 'for months' là cách diễn đạt đúng. 'Since' sẽ sai vì cần đi với một mốc thời gian cụ thể (since last year), không phải một khoảng thời gian chung chung như 'months'." },
  { id: "a159", question: "I need this file ___ Friday at the latest.", options: ["until", "by", "on", "for"], correctIndex: 1, explanation: "'By' mang nghĩa hạn chót, càng được củng cố rõ hơn bởi cụm 'at the latest' (chậm nhất là). Câu này nói cần file này trước thứ Sáu nên 'by' là lựa chọn đúng. 'Until' sẽ sai vì không phù hợp với ý nghĩa 'hạn chót cần hoàn thành', mà chỉ diễn tả một hành động kéo dài liên tục." },
  { id: "a160", question: "She worked ___ the night to finish the project.", options: ["during", "throughout", "in", "at"], correctIndex: 1, explanation: "'Throughout' nhấn mạnh việc một hành động diễn ra xuyên suốt toàn bộ một khoảng thời gian, không ngắt quãng, mạnh hơn 'during' về mặt liên tục. Câu này nói cô ấy làm việc suốt đêm để hoàn thành dự án nên 'throughout' là lựa chọn phù hợp, nhấn mạnh không nghỉ. 'During' cũng đúng ngữ pháp nhưng không nhấn mạnh được tính liên tục xuyên suốt bằng 'throughout'." },
  { id: "a161", question: "He is next ___ me in the queue.", options: ["to", "beside", "by", "near"], correctIndex: 0, explanation: "Cụm cố định 'next to' nghĩa là ngay bên cạnh, tiếp giáp trực tiếp, tương đương với 'beside'. Câu này nói anh ấy đứng ngay sau tôi trong hàng nên 'next to' là lựa chọn tự nhiên. 'Near' sẽ kém chính xác hơn vì 'near' chỉ mang nghĩa 'gần' chung chung, không nhấn mạnh sự liền kề sát cạnh như 'next to'." },
  { id: "a162", question: "She sat ___ her best friend during the ceremony.", options: ["next to", "beside", "near", "opposite"], correctIndex: 1, explanation: "'Beside' nghĩa là ngay sát bên cạnh, diễn tả vị trí liền kề tương tự như 'next to'. Câu này nói cô ấy ngồi ngay cạnh bạn thân trong suốt buổi lễ nên 'beside' là lựa chọn phù hợp. 'Opposite' sẽ sai vì đó là vị trí đối diện nhau, hoàn toàn khác với việc ngồi kề sát bên cạnh." },
  { id: "a163", question: "The coffee shop is ___ the bank — they face each other.", options: ["next to", "beside", "opposite", "near"], correctIndex: 2, explanation: "'Opposite' dùng khi hai vật hay hai địa điểm nằm đối diện nhau qua một khoảng trống như con đường. Câu này nói quán cà phê và ngân hàng đối diện nhau nên 'opposite' là lựa chọn chính xác, được xác nhận thêm bởi cụm 'they face each other'. 'Next to' sẽ sai vì đó là vị trí liền kề bên cạnh, không phải đối diện qua một khoảng cách." },
  { id: "a164", question: "She stood ___ the window, looking out at the rain.", options: ["at", "by", "in", "on"], correctIndex: 1, explanation: "'By' ở đây mang nghĩa 'ngay bên cạnh, gần kề', thường dùng với cửa sổ, cửa ra vào, lò sưởi: by the window, by the door. Câu này nói cô ấy đứng cạnh cửa sổ nhìn ra mưa nên 'by' là lựa chọn tự nhiên. 'At' cũng có thể chấp nhận trong một số ngữ cảnh nhưng 'by the window' là cách diễn đạt phổ biến và gợi hình hơn khi miêu tả tư thế đứng dựa gần." },
  { id: "a165", question: "The statue is ___ of the fountain.", options: ["in front", "behind", "opposite", "next to"], correctIndex: 0, explanation: "Cụm cố định 'in front of' nghĩa là ở phía trước một vật gì đó. Câu này nói bức tượng nằm ở phía trước đài phun nước nên 'in front of' là lựa chọn đúng. 'Behind' sẽ mang nghĩa ngược lại hoàn toàn, là ở phía sau chứ không phải phía trước." },
  { id: "a166", question: "The school is ___ the hospital — you can't see it from here.", options: ["behind", "in front of", "next to", "opposite"], correctIndex: 0, explanation: "'Behind' nghĩa là ở phía sau một vật, không thể nhìn thấy trực tiếp từ phía trước. Câu này nói ngôi trường nằm sau bệnh viện, không thể nhìn thấy từ đây nên 'behind' là lựa chọn phù hợp. 'In front of' sẽ sai vì mang nghĩa ngược lại là ở phía trước, không khớp với việc 'không thể nhìn thấy' như câu miêu tả." },
  { id: "a167", question: "The supermarket is ___ the hotel — just a short walk.", options: ["next to", "near", "opposite", "behind"], correctIndex: 1, explanation: "'Near' nghĩa là gần, ở khoảng cách không xa, nhưng không nhất thiết phải liền kề sát cạnh như 'next to'. Câu này nói siêu thị chỉ cách khách sạn một đoạn đi bộ ngắn nên 'near' là lựa chọn phù hợp hơn là 'next to' (vốn đòi hỏi vị trí sát cạnh trực tiếp). Đây là điểm khác biệt cần lưu ý: 'near' linh hoạt hơn về khoảng cách, còn 'next to' nhấn mạnh sự liền kề." },
  { id: "a168", question: "They discussed the problem ___ the meeting.", options: ["during", "in", "at", "on"], correctIndex: 0, explanation: "'During' dùng với danh từ chỉ một sự kiện có khung thời gian xác định như cuộc họp, hội nghị. Câu này nói họ bàn về vấn đề trong cuộc họp nên 'during' là lựa chọn đúng. 'In' sẽ kém tự nhiên hơn vì 'during' mới là giới từ chuẩn khi nói về việc gì xảy ra trong suốt một sự kiện cụ thể." },
  { id: "a169", question: "Her office is ___ the fifth floor.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Nhắc lại quy tắc số tầng luôn đi với 'on': on the fifth floor. Câu này nói văn phòng cô ấy ở tầng năm nên 'on' là đáp án đúng. 'In' hay 'at' đều không phù hợp với cách diễn đạt số tầng theo quy ước tiếng Anh." },
  { id: "a170", question: "I'll call you ___ I arrive.", options: ["during", "when", "while", "at"], correctIndex: 1, explanation: "'When' dùng để giới thiệu một sự kiện xảy ra tại một thời điểm cụ thể (tôi đến nơi), còn 'while' dùng cho hành động đang diễn ra kéo dài. Câu này nói sẽ gọi ngay khi đến nơi, một hành động xảy ra tức thời nên 'when' là lựa chọn đúng. 'While' sẽ kém phù hợp vì thường đi kèm động từ ở dạng tiếp diễn để chỉ hành động đang xảy ra song song, không phù hợp với hành động 'arrive' mang tính thời điểm." },
  { id: "a171", question: "She is ___ the phone — can you call back?", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Nhắc lại cụm cố định 'on the phone' nghĩa là đang nói chuyện điện thoại. Câu này nói cô ấy đang bận nghe máy nên 'on' là đáp án đúng. Đây là cụm từ cần học thuộc như một khối cố định, không thể thay bằng 'in' hay 'at'." },
  { id: "a172", question: "He is ___ holiday this week.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Cụm cố định 'on holiday' (Anh-Anh) nghĩa là đang trong kỳ nghỉ lễ, tương đương 'on vacation' trong tiếng Anh Mỹ. Câu này nói anh ấy đang nghỉ lễ tuần này nên 'on' là lựa chọn đúng. 'In' hay 'at' đều không đi cùng với 'holiday' theo cách dùng chuẩn này." },
  { id: "a173", question: "The report came out ___ time — no delays.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Cụm cố định 'on time' nghĩa là đúng giờ, đúng như lịch trình đã định, cần phân biệt rõ với 'in time' nghĩa là kịp lúc, không quá muộn. Câu này nói báo cáo ra đúng hẹn không có sự chậm trễ nào nên 'on time' là lựa chọn chính xác. Đây là cặp cụm từ rất dễ gây nhầm lẫn nên cần ghi nhớ sự khác biệt về nghĩa giữa 'on time' và 'in time'." },
  { id: "a174", question: "She arrived just ___ time to catch the train.", options: ["in", "on", "at", "by"], correctIndex: 0, explanation: "Cụm cố định 'in time' nghĩa là kịp lúc, vừa đủ để không bị lỡ mất điều gì, khác với 'on time' nghĩa là đúng giờ theo lịch trình. Câu này nói cô ấy đến vừa kịp để bắt được chuyến tàu nên 'in time' là lựa chọn đúng, được củng cố bởi từ 'just' phía trước. Nếu dùng 'on time' ở đây sẽ không sai ngữ pháp nhưng không diễn tả đúng sắc thái 'suýt lỡ, may mà kịp' như 'in time' thể hiện." },
  { id: "a175", question: "He is ___ charge of the marketing department.", options: ["in", "on", "at", "with"], correctIndex: 0, explanation: "Cụm cố định 'in charge of' nghĩa là chịu trách nhiệm về, phụ trách một mảng công việc nào đó. Câu này nói anh ấy phụ trách bộ phận marketing nên 'in' là giới từ đúng trong cụm này. Đây là cụm từ cố định cần học thuộc trọn vẹn, không thể thay 'in' bằng 'on' hay 'at'." },
  { id: "a176", question: "She is ___ good terms with all her colleagues.", options: ["in", "on", "at", "with"], correctIndex: 1, explanation: "Cụm cố định 'on good terms with' nghĩa là có mối quan hệ tốt đẹp với ai. Câu này nói cô ấy có quan hệ tốt với tất cả đồng nghiệp nên 'on' là giới từ đúng trong cụm này. Cần học thuộc cả cụm để tránh nhầm sang 'in' hay 'at good terms', vốn không đúng theo cách dùng tự nhiên của tiếng Anh." },
  { id: "a177", question: "The exam will be ___ Tuesday morning.", options: ["in", "on", "at", "by"], correctIndex: 1, explanation: "Khi một buổi trong ngày đi kèm tên ngày cụ thể, giới từ chuyển từ 'in' sang 'on': on Tuesday morning. Câu này nói kỳ thi sẽ diễn ra vào sáng thứ Ba nên 'on' là đáp án đúng. Đây là điểm cần nhớ tương tự câu về 'on the morning of June 3rd' đã gặp trước đó: có ngày cụ thể đi kèm thì luôn dùng 'on', không dùng 'in the morning' thông thường." },
  { id: "a178", question: "She tends ___ overreact in stressful situations.", options: ["to", "for", "of", "at"], correctIndex: 0, explanation: "Cụm động từ cố định 'tend to + V nguyên thể' nghĩa là có xu hướng làm gì. Câu này nói cô ấy có xu hướng phản ứng thái quá khi căng thẳng nên 'to' là giới từ/liên từ đúng theo sau bởi động từ nguyên mẫu. 'For' là lỗi cần tránh vì 'tend' không bao giờ đi cùng giới từ này." },
  { id: "a179", question: "He's looking ___ a new job.", options: ["for", "at", "into", "after"], correctIndex: 0, explanation: "Cụm động từ cố định 'look for' nghĩa là tìm kiếm, cần phân biệt với 'look at' (nhìn vào) và 'look after' (chăm sóc). Câu này nói anh ấy đang tìm một công việc mới nên 'for' là giới từ đúng. Ba cụm động từ với 'look' này rất dễ gây nhầm lẫn vì gần giống nhau về mặt hình thức nhưng mang nghĩa hoàn toàn khác nhau." },
  { id: "a180", question: "She has to deal ___ a lot of pressure at work.", options: ["of", "with", "about", "for"], correctIndex: 1, explanation: "Cụm động từ cố định 'deal with + danh từ' nghĩa là xử lý, đối phó với một vấn đề hay áp lực nào đó. Câu này nói cô ấy phải đối phó với nhiều áp lực trong công việc nên 'with' là giới từ đúng. 'Of' là lựa chọn sai thường gặp vì 'deal' theo nghĩa này luôn cần đi cùng 'with'." },
  { id: "a181", question: "He takes pride ___ his work.", options: ["of", "in", "for", "about"], correctIndex: 1, explanation: "Cụm cố định 'take pride in + danh từ/V-ing' nghĩa là tự hào về điều gì, đặc biệt là công việc hay thành quả của bản thân. Câu này nói anh ấy tự hào về công việc của mình nên 'in' là giới từ đúng. 'Of' là lỗi cần tránh vì cụm này luôn cố định với 'in', không phải 'of'." },
  { id: "a182", question: "She has a talent ___ drawing.", options: ["of", "for", "in", "at"], correctIndex: 1, explanation: "Cụm cố định 'a talent for + danh từ/V-ing' nghĩa là có tài năng về một lĩnh vực nào đó. Câu này nói cô ấy có tài vẽ tranh nên 'for' là giới từ đúng. 'In' hay bị chọn nhầm nhưng cụm danh từ 'talent' luôn cần đi cùng 'for'." },
  { id: "a183", question: "He had an impact ___ many young designers.", options: ["in", "on", "to", "for"], correctIndex: 1, explanation: "Cụm cố định 'have an impact on + danh từ' nghĩa là có tác động đến điều gì/ai. Câu này nói anh ấy có tác động lớn đến nhiều nhà thiết kế trẻ nên 'on' là giới từ đúng. 'In' là lỗi phổ biến cần tránh vì 'impact' theo cách dùng này luôn cần 'on'." },
  { id: "a184", question: "She has a passion ___ classical music.", options: ["of", "for", "in", "about"], correctIndex: 1, explanation: "Cụm cố định 'a passion for + danh từ' nghĩa là niềm đam mê dành cho điều gì. Câu này nói cô ấy có niềm đam mê với nhạc cổ điển nên 'for' là giới từ đúng. 'In' là lựa chọn sai thường gặp vì danh từ 'passion' luôn đi cùng giới từ 'for'." },
  { id: "a185", question: "He is involved ___ several charitable organizations.", options: ["in", "with", "at", "for"], correctIndex: 0, explanation: "Cụm tính từ cố định 'involved in + danh từ' nghĩa là tham gia/có liên quan đến một hoạt động hay tổ chức nào đó. Câu này nói anh ấy tham gia vào nhiều tổ chức từ thiện nên 'in' là giới từ đúng. 'With' cũng có thể xuất hiện trong vài ngữ cảnh khác của 'involved', nhưng khi nói về việc tham gia vào một tổ chức/hoạt động, 'in' là lựa chọn chuẩn hơn." },
  { id: "a186", question: "She was disappointed ___ the outcome.", options: ["with", "at", "in", "about"], correctIndex: 0, explanation: "Cụm tính từ cố định 'disappointed with/in + danh từ' nghĩa là thất vọng về điều gì hoặc ai. Câu này nói cô ấy thất vọng về kết quả nên 'with' là giới từ phù hợp nhất trong các lựa chọn. 'At' ít khi đi cùng 'disappointed' theo cách dùng chuẩn, nên cần phân biệt rõ với 'with' và 'in'." },
  { id: "a187", question: "He is enthusiastic ___ the new project.", options: ["for", "about", "in", "at"], correctIndex: 1, explanation: "Cụm tính từ cố định 'enthusiastic about + danh từ/V-ing' nghĩa là nhiệt tình/hào hứng với điều gì. Câu này nói anh ấy rất nhiệt tình với dự án mới nên 'about' là giới từ đúng. 'For' là lỗi thường gặp cần tránh vì 'enthusiastic' không đi cùng giới từ này." },
  { id: "a188", question: "She is allergic ___ shellfish.", options: ["for", "of", "to", "at"], correctIndex: 2, explanation: "Cụm tính từ cố định 'allergic to + danh từ' nghĩa là dị ứng với một chất/thức ăn nào đó. Câu này nói cô ấy dị ứng với hải sản có vỏ nên 'to' là giới từ đúng. 'Of' là lựa chọn sai thường gặp vì 'allergic' luôn cần đi cùng 'to'." },
  { id: "a189", question: "He is suitable ___ the position.", options: ["for", "to", "in", "at"], correctIndex: 0, explanation: "Cụm tính từ cố định 'suitable for + danh từ' nghĩa là phù hợp với vị trí/mục đích nào đó. Câu này nói anh ấy phù hợp với vị trí này nên 'for' là giới từ đúng. 'To' là lỗi cần tránh vì 'suitable' không đi cùng giới từ đó theo cách dùng chuẩn." },
  { id: "a190", question: "She is jealous ___ her sister's success.", options: ["of", "about", "for", "with"], correctIndex: 0, explanation: "Cụm tính từ cố định 'jealous of + danh từ/đại từ' nghĩa là ghen tị với ai/điều gì. Câu này nói cô ấy ghen tị với thành công của em gái nên 'of' là giới từ đúng. 'About' là lựa chọn sai thường gặp vì 'jealous' luôn cần đi cùng 'of'." },
  { id: "a191", question: "He is generous ___ his money and time.", options: ["in", "with", "of", "about"], correctIndex: 1, explanation: "Cụm tính từ cố định 'generous with + danh từ' nghĩa là hào phóng, rộng rãi về tiền bạc hay thời gian. Câu này nói anh ấy rất hào phóng về tiền bạc và thời gian nên 'with' là giới từ đúng. Lưu ý cấu trúc khác 'generous of + person' (thật tốt bụng khi ai đó làm gì) dùng trong ngữ cảnh riêng, không áp dụng ở đây vì câu đang nói về đối tượng là tiền bạc/thời gian chứ không phải hành động của một người." },
  { id: "a192", question: "She struggled ___ understand the instructions.", options: ["to", "for", "with", "in"], correctIndex: 0, explanation: "Cụm động từ 'struggle to + V nguyên thể' nghĩa là vật lộn, cố gắng hết sức để làm điều gì đó khó khăn. Câu này nói anh ấy cố gắng để hiểu các hướng dẫn nên 'to' là lựa chọn đúng, theo sau là động từ nguyên mẫu. 'With' là lỗi cần tránh vì tuy 'struggle with something' cũng tồn tại (vật lộn với một vấn đề - danh từ), nhưng khi theo sau là động từ, phải dùng 'to'." },
  { id: "a193", question: "He is an expert ___ cybersecurity.", options: ["at", "in", "on", "of"], correctIndex: 1, explanation: "Cụm danh từ cố định 'expert in + lĩnh vực' nghĩa là chuyên gia về một lĩnh vực nào đó. Câu này nói anh ấy là chuyên gia về an ninh mạng nên 'in' là giới từ đúng. 'At' hay 'on' là lựa chọn sai thường gặp vì danh từ 'expert' theo sau bởi lĩnh vực luôn cần 'in'." },
  { id: "a194", question: "She has a lot of experience ___ project management.", options: ["at", "in", "on", "of"], correctIndex: 1, explanation: "Cụm cố định 'experience in + lĩnh vực/hoạt động' nghĩa là có kinh nghiệm trong một lĩnh vực nào đó. Câu này nói cô ấy có nhiều kinh nghiệm quản lý dự án nên 'in' là giới từ đúng. 'On' là lựa chọn sai thường gặp vì 'experience' theo cách dùng này cần đi cùng 'in'." },
  { id: "a195", question: "He is deeply concerned ___ climate change.", options: ["of", "about", "for", "with"], correctIndex: 1, explanation: "Cụm tính từ cố định 'concerned about + danh từ' nghĩa là lo ngại sâu sắc về điều gì. Câu này nói anh ấy rất lo ngại về biến đổi khí hậu nên 'about' là giới từ đúng. 'Of' là lựa chọn sai thường gặp vì 'concerned' theo nghĩa lo lắng luôn cần đi cùng 'about'." },
  { id: "a196", question: "She is fluent ___ three languages.", options: ["at", "in", "on", "with"], correctIndex: 1, explanation: "Cụm tính từ cố định 'fluent in + ngôn ngữ' nghĩa là thông thạo một ngôn ngữ nào đó. Câu này nói cô ấy thông thạo ba ngôn ngữ nên 'in' là giới từ đúng. 'At' là lỗi cần tránh vì 'fluent' không đi cùng giới từ này khi nói về ngôn ngữ." },
  { id: "a197", question: "He adapted quickly ___ the new environment.", options: ["at", "in", "to", "for"], correctIndex: 2, explanation: "Cụm động từ cố định 'adapt to + danh từ' nghĩa là thích nghi với một môi trường hay hoàn cảnh mới. Câu này nói anh ấy nhanh chóng thích nghi với môi trường mới nên 'to' là giới từ đúng. 'In' là lựa chọn sai thường gặp vì 'adapt' luôn cần đi cùng 'to'." },
  { id: "a198", question: "She contributed greatly ___ the success of the project.", options: ["in", "on", "to", "for"], correctIndex: 2, explanation: "Cụm động từ cố định 'contribute to + danh từ' nghĩa là đóng góp vào một điều gì đó. Câu này nói cô ấy đóng góp rất nhiều vào thành công của dự án nên 'to' là giới từ đúng. 'On' là lựa chọn sai thường gặp vì 'contribute' luôn cần đi cùng 'to'." },
  { id: "a199", question: "He objected strongly ___ the proposed changes.", options: ["at", "to", "about", "against"], correctIndex: 1, explanation: "Cụm động từ cố định 'object to + danh từ/V-ing' nghĩa là phản đối điều gì. Câu này nói anh ấy phản đối mạnh mẽ những thay đổi được đề xuất nên 'to' là giới từ đúng. 'Against' tuy gần nghĩa nhưng không phải cách dùng chuẩn với động từ 'object', nên cần chọn 'to' thay vì 'against'." },
  { id: "a200", question: "She referred ___ the manual for guidance.", options: ["at", "in", "to", "on"], correctIndex: 2, explanation: "Cụm động từ cố định 'refer to + danh từ' nghĩa là tham khảo hoặc đề cập đến điều gì. Câu này nói cô ấy tham khảo cuốn hướng dẫn để được chỉ dẫn nên 'to' là giới từ đúng. 'On' là lựa chọn sai thường gặp vì 'refer' luôn cần đi cùng 'to'." },
];
